function d85($s){$a='0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz!#$%&()*+-;<=>?@^_`{|}~';$p=(5-($s.Length%5))%5;if($p){$s+=('~'*$p)};$o=New-Object System.Collections.Generic.List[byte];for($i=0;$i -lt $s.Length;$i+=5){$v=[uint64]0;for($j=0;$j -lt 5;$j++){$v=$v*85+$a.IndexOf($s[$i+$j])};$o.Add([byte](($v-shr24)-band255));$o.Add([byte](($v-shr16)-band255));$o.Add([byte](($v-shr8)-band255));$o.Add([byte]($v-band255))};$r=$o.ToArray();if($p){$r=$r[0..($r.Length-$p-1)]};,$r}
$m=[IO.MemoryStream]::new((d85 $c))
$g=[IO.Compression.DeflateStream]::new($m,[IO.Compression.CompressionMode]::Decompress)
